CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '' CHECK (length(display_name) <= 100), avatar_url text, preferences jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), daily_generations integer NOT NULL DEFAULT 5 CHECK (daily_generations >= 0), generations_used integer NOT NULL DEFAULT 0 CHECK (generations_used >= 0), generations_reset_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.profiles TO authenticated;
GRANT UPDATE (display_name, avatar_url, preferences) ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profiles_read_own ON public.profiles FOR SELECT TO authenticated USING (id = auth.uid());
CREATE POLICY profiles_update_own ON public.profiles FOR UPDATE TO authenticated USING (id = auth.uid()) WITH CHECK (id = auth.uid());
CREATE FUNCTION public.roomvar_create_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN INSERT INTO public.profiles (id, display_name) VALUES (NEW.id, left(coalesce(NEW.raw_user_meta_data->>'display_name', NEW.raw_user_meta_data->>'full_name', NEW.raw_user_meta_data->>'name', ''), 100)) ON CONFLICT (id) DO NOTHING; RETURN NEW; END; $$;
REVOKE EXECUTE ON FUNCTION public.roomvar_create_profile() FROM PUBLIC, anon, authenticated;
CREATE TRIGGER roomvar_profile_on_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.roomvar_create_profile();
CREATE TABLE public.conversations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL DEFAULT auth.uid() REFERENCES public.profiles(id) ON DELETE CASCADE, title text NOT NULL CHECK (length(title) BETWEEN 1 AND 200), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.conversations TO authenticated;
GRANT ALL ON public.conversations TO service_role;
ALTER TABLE public.conversations ENABLE ROW LEVEL SECURITY;
CREATE POLICY conversations_own ON public.conversations FOR ALL TO authenticated USING (user_id = auth.uid()) WITH CHECK (user_id = auth.uid());
CREATE TABLE public.messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), conversation_id uuid NOT NULL REFERENCES public.conversations(id) ON DELETE CASCADE, role text NOT NULL CHECK (role IN ('user','assistant','system')), content text NOT NULL DEFAULT '' CHECK (length(content) <= 100000), image_url text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.messages TO authenticated;
GRANT ALL ON public.messages TO service_role;
ALTER TABLE public.messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY messages_own ON public.messages FOR ALL TO authenticated USING (EXISTS (SELECT 1 FROM public.conversations c WHERE c.id = conversation_id AND c.user_id = auth.uid())) WITH CHECK (EXISTS (SELECT 1 FROM public.conversations c WHERE c.id = conversation_id AND c.user_id = auth.uid()));
CREATE TABLE public.gallery (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL DEFAULT auth.uid() REFERENCES public.profiles(id) ON DELETE CASCADE, prompt text NOT NULL CHECK (length(prompt) <= 6000), image_url text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.gallery TO authenticated;
GRANT ALL ON public.gallery TO service_role;
ALTER TABLE public.gallery ENABLE ROW LEVEL SECURITY;
CREATE POLICY gallery_own ON public.gallery FOR ALL TO authenticated USING (user_id = auth.uid()) WITH CHECK (user_id = auth.uid());
CREATE INDEX conversations_owner_updated ON public.conversations(user_id, updated_at DESC);
CREATE INDEX messages_thread_created ON public.messages(conversation_id, created_at);
CREATE INDEX gallery_owner_created ON public.gallery(user_id, created_at DESC);
CREATE FUNCTION public.get_image_quota() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE p public.profiles; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'not authenticated'; END IF; UPDATE public.profiles SET generations_used = 0, generations_reset_at = now() WHERE id = auth.uid() AND now() >= generations_reset_at + interval '12 hours'; SELECT * INTO p FROM public.profiles WHERE id = auth.uid(); IF NOT FOUND THEN RETURN jsonb_build_object('used', 0, 'limit', 5, 'reset_at', now() + interval '12 hours'); END IF; RETURN jsonb_build_object('used', p.generations_used, 'limit', p.daily_generations, 'reset_at', p.generations_reset_at + interval '12 hours'); END; $$;
CREATE FUNCTION public.consume_image_generation(_user_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE p public.profiles; BEGIN UPDATE public.profiles SET generations_used = 0, generations_reset_at = now() WHERE id = _user_id AND now() >= generations_reset_at + interval '12 hours'; UPDATE public.profiles SET generations_used = generations_used + 1 WHERE id = _user_id AND generations_used < daily_generations RETURNING * INTO p; IF NOT FOUND THEN SELECT * INTO p FROM public.profiles WHERE id = _user_id; RETURN jsonb_build_object('allowed', false, 'used', coalesce(p.generations_used,0), 'limit', coalesce(p.daily_generations,5), 'reset_at', p.generations_reset_at + interval '12 hours'); END IF; RETURN jsonb_build_object('allowed', true, 'used', p.generations_used, 'limit', p.daily_generations, 'reset_at', p.generations_reset_at + interval '12 hours'); END; $$;
CREATE FUNCTION public.refund_image_generation(_user_id uuid) RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path = public AS $$ UPDATE public.profiles SET generations_used = greatest(generations_used - 1, 0) WHERE id = _user_id; $$;
REVOKE EXECUTE ON FUNCTION public.get_image_quota() FROM PUBLIC, anon;
REVOKE EXECUTE ON FUNCTION public.consume_image_generation(uuid) FROM PUBLIC, anon, authenticated;
REVOKE EXECUTE ON FUNCTION public.refund_image_generation(uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.get_image_quota() TO authenticated;
GRANT EXECUTE ON FUNCTION public.consume_image_generation(uuid) TO service_role;
GRANT EXECUTE ON FUNCTION public.refund_image_generation(uuid) TO service_role;